content.text:
{ lib, ... }:
{
  options.flake.lib.factory = lib.mkOption {
    type = lib.types.attrsOf lib.types.unspecified;
    default = { };
  };
}

{
  inputs,
  self,
  lib,
  ...
}:
{
  flake.lib.factory.mkHost =
    {
      name ? throw "You must provide a valid host name",
      system ? "x86_64-linux",
    }:
    (inputs.nixpkgs.lib.nixosSystem {
      modules = [
        self.modules.nixos.${name}
        (
          { pkgs, ... }:
          {
            nixpkgs.hostPlatform = lib.mkDefault system;
            networking.hostName = "${name}";
            system.stateVersion = "26.05";
            programs.nh.enable = true;
            programs.git.enable = true;
            environment.systemPackages = with pkgs; [
              gitui
              inputs.home-manager.packages.${system}.home-manager
              inputs.disko.packages.${system}.disko
            ];
            environment.etc = {
              nixos-setup = {
                source = ../..;
              };
            };
          }
        )
      ];
    });
}

{
  lib,
  ...
}:
{
  flake.lib.factory.mkUser =
    {
      name ? throw "You must provide a valid username",
      uid ? throw "You must provide a valid uid",
      isAdmin ? false,
      hasNetworkAccess ? false,
    }:
    {
      nixos.${name} = {
        users.groups.${name} = { };
        users.users.${name} = {
          group = "${name}";
          isNormalUser = true;
          extraGroups = lib.mkMerge [
            (lib.mkIf isAdmin [ "wheel" ])
            (lib.mkIf hasNetworkAccess [ "networkmanager" ])
            [ "input" ]
          ];
          inherit uid;
          initialPassword = "${name}";
        };
      };
      homeManager.${name} = {
        home = {
          username = "${name}";
          homeDirectory = "/home/${name}";
          inherit uid;
        };
      };
    };
}

{
  inputs,
  self,
  lib,
  ...
}:
{
  flake.lib.factory.mkHomeConfiguration =
    {
      user ? throw "You must provide a homeConfiguration user",
      system ? "x86_64-linux",
      extraModules ? [ ],
    }:
    (inputs.home-manager.lib.homeManagerConfiguration {
      pkgs = import inputs.nixpkgs { inherit system; };
      extraSpecialArgs = { inherit inputs; };
      modules = lib.concatLists [
        extraModules
        [
          self.modules.homeManager.${user}
          (
            { pkgs, ... }:
            {
              nix.package = pkgs.nix;
              home = {
                username = lib.mkDefault "${user}";
                homeDirectory = lib.mkDefault "/home/${user}";
                stateVersion = lib.mkDefault "26.05";
              };
            }
          )
        ]
      ];
    });
}

let
  layout = "mkSimpleNoSwap";
in
{ inputs, ... }:
{
  flake.lib.diskoLayoutFactory.${layout} =
    {
      deviceName ? throw "A device name is needed. ('disk-label')",
      device ? throw "A device is needed. (/dev/sda)",
      host ? throw "A valid hostname is needed.",
    }:
    {
      nixos."${host}" =
        { pkgs, ... }:
        {
          imports = [
            inputs.disko.nixosModules.disko
          ];
          environment.systemPackages = with pkgs; [
            disko
          ];
          disko.devices = {
            disk = {
              "${deviceName}" = {
                type = "disk";
                inherit device;
                content = {
                  type = "gpt";
                  partitions = {
                    ESP = {
                      size = "1G";
                      type = "EF00";
                      content = {
                        type = "filesystem";
                        format = "vfat";
                        mountpoint = "/boot";
                        mountOptions = [ "umask=0077" ];
                      };
                    };
                    root = {
                      size = "100%";
                      content = {
                        type = "filesystem";
                        format = "ext4";
                        mountpoint = "/";
                      };
                    };
                  };
                };
              };
            };
          };
        };
    };
}

{ lib, ... }:
{
  options.flake.lib.diskoLayoutFactory = lib.mkOption {
    type = lib.types.attrsOf lib.types.unspecified;
    default = { };
  };
}

{ inputs, ... }:
{
  flake.lib.factory.mkSystemSecrets =
    {
      owner ? throw "You must provide a secrets owner",
      defaultSopsFormat ? "yaml",
      keyFile ? "/home/${owner}/.config/sops/age/keys.txt",
      defaultSopsFile ? throw "You must provide a 'secrets' file matching your defined format",
      secrets ? [ ],
    }:
    {
      nixos."${owner}-system-secrets" =
        {
          pkgs,
          ...
        }:
        {
          imports = [
            inputs.sops-nix.nixosModules.sops
          ];

          environment.systemPackages = with pkgs; [
            sops
            ssh-to-age
          ];

          sops = {
            inherit defaultSopsFile defaultSopsFormat;
            age = {
              inherit keyFile;
              generateKey = false;
            };
            secrets =
              let
                modList = map (x: {
                  name = x;
                  value = {
                    inherit owner;
                  };
                }) secrets;
                result = (builtins.listToAttrs modList);
              in
              result;
          };
        };
    };
}

{ inputs, ... }:
{
  flake.lib.factory.mkUserSecrets =
    {
      owner ? throw "You must provide a secrets owner",
      defaultSopsFormat ? "yaml",
      keyFile ? "/home/${owner}/.config/sops/age/keys.txt",
      defaultSopsFile ? throw "You must provide a 'secrets' file matching your defined format",
      secrets ? [ ],
    }:
    {
      homeModules."${owner}-secrets" =
        {
          pkgs,
          config,
          ...
        }:
        {
          imports = [
            inputs.sops-nix.homeManagerModules.sops
          ];

          home.packages = with pkgs; [
            sops
            ssh-to-age
          ];

          sops = {
            inherit defaultSopsFile defaultSopsFormat;
            age = { inherit keyFile; };
            secrets = builtins.listToAttrs (
              map (x: {
                name = "${x}";
                value = {
                  owner = config.users.users.${owner}.name;
                };
              }) secrets
            );
          };
        };
    };
}

{
  inputs,
  self,
  lib,
  ...
}:
{
  flake.lib.factory.mkOfflineInstaller =
    {
      name ? throw "You must provide a valid host name",
      system ? "x86_64-linux",
    }:
    (inputs.nixpkgs.lib.nixosSystem {
      inherit system;
      modules = [
        self.modules.nixos.${name}
        (
          { pkgs, modulesPath, ... }:
          let
            flakeOutPaths =
              let
                collector =
                  visited: parent:
                  lib.concatMap (
                    child:
                    if lib.elem child.outPath visited then
                      [ ]
                    else
                      let
                        newVisited = visited ++ [ child.outPath ];
                      in
                      [ child.outPath ]
                      ++ (if child ? inputs && child.inputs != { } then collector newVisited child else [ ])
                  ) (lib.attrValues parent.inputs);
              in
              lib.unique (collector [ ] { inputs = inputs; });
            dependencies = [
              self.nixosConfigurations.${name}.config.system.build.toplevel
              self.nixosConfigurations.${name}.config.system.build.diskoScript
              self.nixosConfigurations.${name}.config.system.build.diskoScript.drvPath
              self.nixosConfigurations.${name}.pkgs.stdenv.drvPath
              self.nixosConfigurations.${name}.pkgs.perlPackages.ConfigIniFiles
              self.nixosConfigurations.${name}.pkgs.perlPackages.FileSlurp
              (self.nixosConfigurations.${name}.pkgs.closureInfo { rootPaths = [ ]; }).drvPath
            ]
            ++ flakeOutPaths;
            closureInfo = pkgs.closureInfo { rootPaths = dependencies; };
          in
          {
            nixpkgs.hostPlatform = lib.mkDefault system;
            networking.hostName = "${name}-offline-installer";
            system.stateVersion = "26.05";
            programs.nh.enable = true;
            programs.git.enable = true;

            system.includeBuildDependencies = true;

            environment.systemPackages = with pkgs; [
              gitui
              inputs.home-manager.packages.${pkgs.stdenv.hostPlatform.system}.home-manager
              inputs.disko.packages.${pkgs.stdenv.hostPlatform.system}.disko
              (pkgs.writeShellScriptBin "disko-install-wrapper" ''
                exec ${
                  inputs.disko.packages.${pkgs.stdenv.hostPlatform.system}.disko
                }/bin/disko-install --flake "${self}#${name}" "$@"
              '')
            ];

            environment.etc = {
              nixos-setup = {
                source = "${self}";
              };
              "install-closure".source = "${closureInfo}/store-paths";
              "system-closure-path".text = "${self.nixosConfigurations.${name}.config.system.build.toplevel}";
              "system-flake".text = "${self}";
            };
          }
        )
      ];
    });
}

