              blocklist_txt = pkgs.writeText "blocklist.txt" ''
                ${extraBlocklist}
                ${blocklist_base}
              '';
            in
            blocklist_txt;
        };
      };
      systemd.services.dnscrypt-proxy.serviceConfig.StateDirectory = StateDirectory;

    };
