let
  feature = "nightmare-hyprland";
in
{
  self,
  inputs,
  ...
}:
{
  flake.modules.homeManager.${feature} =
    {
      pkgs,
      lib,
      config,
      ...
    }:
    let
      toLua = x: lib.generators.mkLuaInline x;
    in
    {
      imports = with self.modules.homeManager; [
        hyprland
      ];
      home.packages = with pkgs; [
        wf-recorder
      ];
      wayland.windowManager.hyprland = {
        enable = true;
        configType = "lua";
        settings = {
          config = {
            general = {
              locale = "es_PY";
              # master layout for now:
              layout = "master";
              border_size = 2;
              gaps_in = 0;
              gaps_out = 0;
              # gaps_workspaces = 0;
              # float_gaps = 0;
              resize_on_border = true;
              extend_border_grab_area = true;
              hover_icon_on_border = true;
              allow_tearing = true;
              # modal_parent_blocking = true;
              # snap = { };
            };
            cursor = {
              no_hardware_cursors = 2;
              use_cpu_buffer = 2;
            };
            decoration = {
              rounding = 0;
              # active_opacity = 0.90;
              # inactive_opacity = 0.85;
              fullscreen_opacity = 1.0;
              blur = {
                enabled = false;
                size = 8;
                passes = 2;
                ignore_opacity = true;
                new_optimizations = true;
                xray = false;
                contrast = 1.0;
                brightness = 1.0;
                noise = 0.0;
              };
              shadow = {
                enabled = false;
                range = 8;
                render_power = 3;
                offset = [
                  0
                  0
                ];
              };
              glow = {
                enabled = false;
                range = 8;
                render_power = 3;
                color = lib.mkForce config.lib.stylix.colors.withHashtag.base0D;
                color_inactive = lib.mkForce config.lib.stylix.colors.withHashtag.base04;
              };
            };
            input = {
              kb_layout = "latam";
              follow_mouse = 0;
              mouse_refocus = true;
            };
            group = {
              auto_group = true;
              groupbar = {
                enabled = true;
              };
            };
            misc = {
              disable_hyprland_logo = true;
              disable_splash_rendering = true;
            };
          };
          monitor = [
            {
              output = "eDP-1";
              mode = "preferred";
              position = "0x0";
              scale = 1;
            }
            {
              output = "";
              mode = "highres";
              position = "auto-right";
              scale = 1;
            }
          ];

          workspace_rule = [
            {
              workspace = "r[1-7]";
              monitor = "eDP-1";
              persistent = true;
            }
          ];

          # ---- BINDS ----

          bind = [
            {
              _args = [
                "SUPER + RETURN"
                (lib.generators.mkLuaInline ''hl.dsp.exec_cmd("${pkgs.kitty}/bin/kitty")'')
              ];
            }
            # Experimental:
            # Text to speech to use the Nate Gentile agentic Linux workflow.
            {
              _args = [
                "SUPER + H"
                (lib.generators.mkLuaInline ''hl.dsp.exec_cmd("${pkgs.handy}/bin/handy --toggle-transcription")'')
              ];
            }
            {
              _args = [
                "SUPER + SPACE"
                (lib.generators.mkLuaInline ''
                  hl.dsp.exec_cmd("${pkgs.wofi}/bin/wofi --show drun")
                '')
              ];
            }
            {
              _args = [
                "Print"
                (lib.generators.mkLuaInline ''
                  hl.dsp.exec_cmd("${pkgs.hyprshot}/bin/hyprshot -m active -m output")
                '')
              ];
            }
            {
              _args = [
                "SHIFT + Print"
                (lib.generators.mkLuaInline ''
                  hl.dsp.exec_cmd("${pkgs.hyprshot}/bin/hyprshot -m region")
                '')
              ];
            }
            {
              _args = [
                "SUPER + Q"
                (lib.generators.mkLuaInline ''
                  hl.dsp.window.close()
                '')
              ];
            }
            {
              _args = [
                "SUPER + W"
                (lib.generators.mkLuaInline ''
                  hl.dsp.window.float()
                '')
              ];
            }
            {
              _args = [
                "SUPER + E"
                (lib.generators.mkLuaInline ''
                  hl.dsp.exec_cmd("${pkgs.kitty}/bin/kitty sh -c '${pkgs.yazi}/bin/yazi'", { float = true, center = true, size = {"(monitor_w*0.5)", "(monitor_h*0.5)"} })
                '')
              ];
            }
            {
              _args = [
                "SUPER + R"
                (lib.generators.mkLuaInline ''
                  hl.dsp.exec_cmd("${pkgs.kitty}/bin/kitty sh -c '${pkgs.rmpc}/bin/rmpc --address 127.0.0.1:6600'", { float = true, center = true, size = {"(monitor_w*0.5)", "(monitor_h*0.5)"} })
                '')
              ];
            }
            {
              _args = [
                "SUPER + T"
                (lib.generators.mkLuaInline ''
                  hl.dsp.exec_cmd("${pkgs.kitty}/bin/kitty sh -c '${pkgs.networkmanager}/bin/nmtui'", { float = true, center = true, size = {"(monitor_w*0.5)", "(monitor_h*0.5)"} })
                '')
              ];
            }
            {
              _args = [
                "SUPER + A"
                (lib.generators.mkLuaInline ''
                  hl.dsp.exec_cmd("${
                    inputs.zen-browser.packages.${pkgs.stdenv.hostPlatform.system}.twilight
                  }/bin/zen-twilight")
                '')
              ];
            }
            {
              _args = [
                "SUPER + S"
                (lib.generators.mkLuaInline ''
                  hl.dsp.exec_cmd("${pkgs.vlc}/bin/vlc", { float = true, center = true, size = {"(monitor_w*0.5)", "(monitor_h*0.5)"} })
                '')
              ];
            }
            {
              _args = [
                "SUPER + D"
                # (lib.generators.mkLuaInline ''
                #   hl.dsp.exec_cmd("${pkgs.kitty}/bin/kitty sh -c '${pkgs.helix}/bin/hx'", { float = true, center = true, size = {"(monitor_w*0.5)", "(monitor_h*0.5)"} })
                # '')
                (toLua ''
                  hl.dsp.exec_cmd("${pkgs.wofi}/bin/wofi --show drun")
                '')
              ];
            }
            {
              _args = [
                "SUPER + F"
                (lib.generators.mkLuaInline ''
                  hl.dsp.window.fullscreen()
                '')
              ];
            }
            {
              _args = [
                "SUPER + G"
                (lib.generators.mkLuaInline ''
                  hl.dsp.window.center()
                '')
              ];
            }
            {
              _args = [
                "SUPER + Z"
                (toLua ''
                  hl.dsp.exec_cmd("${pkgs.hyprlock}/bin/hyprlock")
                '')
              ];
            }
            {
              _args = [
                "SUPER + C"
                (toLua ''
                  hl.dsp.exec_cmd("${pkgs.kitty}/bin/kitty sh -c '${pkgs.clock-rs}/bin/clock-rs'", { float = true, center = true, size = { 600, 480 } })
                '')
              ];
            }
            {
              _args = [
                "SUPER + V"
                (toLua ''
                  hl.dsp.exec_cmd("${pkgs.kitty}/bin/kitty sh -c '${pkgs.btop}/bin/btop'", { float = true, center = true, size = {"(monitor_w*0.5)", "(monitor_h*0.5)"} })
