let
  feature = "serpantinum-desktop";
in
{ self, inputs, ... }: {
  flake.modules.nixos.${feature} = { lib, ... }: {
    imports = with self.modules.nixos; [
      serpantinum-shell
    ];
    services.tlp.pd.enable = lib.mkForce false;
    services.tlp.enable = lib.mkForce false;
  };
  flake.modules.homeManager.${feature} = { pkgs, lib, ... }: {
    imports = with self.modules.homeManager; [
      serpantinum-shell
      nightmare-helix
    ];
    home.packages = with pkgs; [
      easyeffects
      wl-clipboard-rs
    ];
    programs.serpantinum = {
      systemd.enable = true;
      settings = {
        wallpaperDir = "${
          self.packages.${pkgs.stdenv.hostPlatform.system}.wanderer-wallpapers
        }/share/wallpapers";

        general = {
          language = "es_PY";
          # weatherUnit = "metric";
          # weatherInterval = 30;
        };

        bar = {
          position = "top";
          style = "solid";
          width = 40;
          workspaceCount = 10;
          modules = {
            left = [ "workspaces" ];
            center = [ "time" ];
            right = [
              "tray"
              [
                "kb"
                "wifi"
                "bt"
                "vol"
                "bat"
              ]
            ];
          };
        };

        theme = {
          fontFamily = "Mononoki Nerd Font";
          borderRadius = 12;
          matugen = true;
        };

        notifications = {
          dnd = false;
          position = "top right";
          sound = true;
        };
      };
    };
    wayland.windowManager.hyprland = {
      settings = {
        on = {
          _args = [
            "hyprland.start"
            (lib.generators.mkLuaInline ''
              function()
                hl.exec_cmd("wl-paste --type text --watch cliphist store")
                hl.exec_cmd("wl-paste --type image --watch cliphist store")
                hl.exec_cmd("systemctl --user enable --now easyeffects")
              end
            '')
          ];
        };
      };
    };
  };
}

let
  package = "colorful-icons";
in
{
  perSystem =
    { pkgs, ... }:
    {
      packages.${package} = pkgs.stdenvNoCC.mkDerivation {
        name = "${package}";
        src = pkgs.fetchFromGitHub {
          owner = "L4ki";
          repo = "Colorful-Plasma-Themes";
          rev = "main";
          hash = "sha256-bC4uAHnR4xZ50nEmG4Xyr0APvgL2r0BMD6b4a8UJbD0=";
        };
        dontBuild = true;
        dontUnpack = true;
        installPhase = ''
          runHook preInstall
          mkdir -p $out/share/icons
          cp -R "$src/Colorful Icons Themes/Colorful-Dark-Icons" $out/share/icons

          runHook postInstall
        '';
        nativeBuildInputs = with pkgs; [
          gtk3
        ];
        propagatedBuildInputs = with pkgs; [
          hicolor-icon-theme
        ];

        dontDropIconThemeCache = true;

      };
    };
}

let
  package = "drift";
in
{
  perSystem =
    { pkgs, lib, ... }:
    let
      qtEnv =
        with pkgs.qt6;
        env "qt-custom-${qtbase.version}" [
          qtdeclarative
        ];
    in
    {
      packages.${package} = pkgs.stdenv.mkDerivation (finalAttrs: {
        pname = "drift";
        version = "0.2.0";
        __structuredAttrs = true;
        strictDeps = true;

        src = pkgs.fetchFromGitHub {
          owner = "CutWire-Studios";
          repo = "Drift";
          tag = "v${finalAttrs.version}";
          hash = "sha256-L3icaBrh2DKRQDh5JTDknW+XgBAcICNp6iijM73j2Yw=";
        };

        nativeBuildInputs = with pkgs; [
          cmake
          zstd
          openssl
          ffmpeg
          qt6Packages.wrapQtAppsHook
          qt6Packages.qtbase
          qt6Packages.qtmultimedia
          qt6Packages.qt5compat
          qt6Packages.qtdeclarative
          # qt5.qtquickcontrols2
          soundtouch
          juce.src
          git
          pkg-config
          qtEnv
          libglvnd
        ];

        buildInputs = with pkgs; [
          qt6Packages.qtbase
          qt6Packages.qtmultimedia
          qt6Packages.qt5compat
          qt6Packages.qtdeclarative
          ffmpeg
          onnx
          onnxruntime
          soundtouch
          juce.src
          pkg-config
        ];

        cmakeFlags = [ "-DDRIFT_JUCE_DIR=${pkgs.juce.src}" ];

        passthru.updateScript = pkgs.nix-update-script { };

        meta = {
          description = "Drift is a free, open-source, beginner-friendly desktop video editor built with Qt 6 and FFmpeg";
          homepage = "https://github.com/CutWire-Studios/Drift";
          changelog = "https://github.com/CutWire-Studios/Drift/blob/${finalAttrs.src.rev}/CHANGELOG.md";
          license = lib.licenses.gpl3Only;
          maintainers = with lib.maintainers; [ ];
          mainProgram = "drift";
          platforms = lib.platforms.all;
        };
      });
    };
}

